int connect_to_server(const char* host, int port) {
    pthread_mutex_lock(&conn_mutex);
    if (connection_count >= max_connections) {
        pthread_mutex_unlock(&conn_mutex);
        return -1;
    }
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    connection_count++;
    pthread_mutex_unlock(&conn_mutex);
    return fd;
}

